describe("trade-war-room lib", () => {
  it("maps the side holding the team's players to OUT", () => {
    const sides = [
      { assets: [{ name: "Theirs" }] },
      {
        assets: [
          { name: "Mine A" },
          { name: "2027 Round 1", assetId: "p1", assetLabel: "2027 1st (own)" },
        ],
      },
    ];
    const r = tradeRequestForTeam(sides, new Set(["Mine A"]), "Us");
    expect(r).toMatchObject({
      mySide: 1,
      playersOut: ["Mine A"],
      picksOut: ["2027 1st (own)"],
      playersIn: ["Theirs"],
    });
  });

  it("refuses malformed or mismatched payloads", () => {
    expect(validAnalyzePayload(null)).toBe(false);
    expect(validAnalyzePayload({ ...CONSOLIDATION, analysis: { recommendation: "MAYBE" } })).toBe(
      false,
    );
    expect(validAnalyzePayload(CONSOLIDATION, { leagueKey: "other" })).toBe(false);
    expect(validAnalyzePayload(CONSOLIDATION, { leagueKey: "main", useTeamContext: true })).toBe(
      true,
    );
    expect(validAnalyzePayload(AJ_BROWN, { leagueKey: "main", useTeamContext: true })).toBe(true);
  });
});

describe("TradeWarRoom — the ONE decision (TC-C)", () => {
  it("NOT ENOUGH EVIDENCE names what is missing and states no confidence level", async () => {
    await renderWith(PARTIAL);
    const d = PARTIAL.analysis.decision;
    expect(d.headline).toBe("NOT_ENOUGH_EVIDENCE");
    expect(screen.getByTestId("decision-headline")).toHaveTextContent(d.headlineText);
    for (const g of d.missingEvidence) {
      expect(
        within(screen.getByTestId("decision-missing")).getByText(missingEvidenceText(g)),
      ).toBeInTheDocument();
    }
    expect(screen.getByTestId("decision-confidence")).toHaveTextContent(
      "No confidence level is given: important information is missing.",
    );
    expect(screen.getByTestId("decision-confidence").textContent).not.toMatch(/High|Medium|Low/);
  });

  it("the strategy control sends an override as teamGoal; its reasoning is one click away", async () => {
    await renderWith(CONSOLIDATION);
    const d = CONSOLIDATION.analysis.decision;
    openSection("Arguments, objections and uncertainty");
    expect(screen.getByTestId("decision-strategy")).toHaveTextContent(strategySentence(d.strategy));
    expect(screen.getByTestId("decision-strategy").textContent).not.toMatch(/PUSH/);
    fireEvent.click(screen.getByRole("radio", { name: "Long-term" }));
    await settle();
    const bodies = globalThis.fetch.mock.calls.map((c) => JSON.parse(c[1].body));
    expect(bodies.at(-1).teamGoal).toBe("LONG_TERM");
    expect(bodies[0].teamGoal).toBeUndefined();
    // The control is an input: it never vanishes while the new answer computes.
    expect(screen.getByRole("radio", { name: "Long-term" })).toHaveAttribute(
      "aria-checked",
      "true",
    );
  });

  it("every backend reason, verbatim, and the bands used are in the methodology", async () => {
    await renderWith(CONSOLIDATION);
    const d = CONSOLIDATION.analysis.decision;
    openSection("Sources, simulations and methodology");
    const record = screen.getByTestId("decision-record");
    for (const r of d.reasons) expect(record).toHaveTextContent(r.text);
    expect(screen.getByTestId("decision-bands")).toHaveTextContent(d.bands.version);
  });

  it("no second verdict: the legacy graded leaning is not shown anywhere in the War Room", async () => {
    // A leaning that disagrees with the decision must not be able to read as
    // a recommendation (owner directive 2026-10-19: one official answer).
    const p = structuredClone(CONSOLIDATION);
    p.analysis.decision.leaning = "PASS";
    const { container } = await renderWith(p);
    for (const name of [
      "Lineup impact, player by player",
      "Your lineup before and after",
      "Arguments, objections and uncertainty",
      "Sources, simulations and methodology",
    ]) {
      openSection(name);
    }
    // Everything except the official headline badge.
    const badge = screen.getByTestId("decision-headline");
    const rest = readText(container).replace(badge.textContent, "");
    expect(rest).not.toMatch(/leaning/i);
    expect(rest).not.toMatch(/Make the trade|Lean make|Lean pass|Too close \/ depends|\bPass\b/);
    expect(screen.getByTestId("decision-headline")).toHaveTextContent(
      p.analysis.decision.headlineText,
    );
  });

  it("Asset only hides the strategy control (no roster, no strategy)", async () => {
    await renderWith(ASSET_ONLY);
    expect(screen.queryByRole("radiogroup", { name: "Strategy" })).toBeNull();
    expect(screen.getByTestId("decision-headline")).toHaveTextContent(
      ASSET_ONLY.analysis.decision.headlineText,
    );
  });

  it("refuses a packet without a recognised decision", () => {
    const broken = structuredClone(CONSOLIDATION);
    delete broken.analysis.decision;
    expect(validAnalyzePayload(broken, { leagueKey: "main", useTeamContext: true })).toBe(false);
  });
});
